    overflow: auto;
    padding: 8px;
    background: rgba(0,0,0,.2);
    border-radius: 18px;
    max-width: 100%;
    -webkit-overflow-scrolling: touch;
  }

  .grid {
    display: grid;
    gap: 7px;
    margin: auto;
    width: max-content;
  }

  .cell {
    width: 72px;
    height: 72px;
    border-radius: 15px;
    border: 1px solid var(--tile-border);
    background: linear-gradient(145deg, #30304a, #232338);
    color: var(--text);
    display: grid;
    place-items: center;
    position: relative;
    user-select: none;
    cursor: pointer;
    box-shadow: inset 0 -8px 15px rgba(0,0,0,.14);
    transition: transform .08s ease, border-color .12s ease, background .12s ease, box-shadow .12s ease, opacity .12s ease;
    touch-action: manipulation;
  }

  .cell:hover {
    transform: translateY(-1px);
  }

  .cell:focus-visible {
    outline: 3px solid rgba(117,240,168,.75);
    outline-offset: 2px;
  }

  .cell.wall {
    background: #11111c;
    border-color: #1b1b2b;
    cursor: not-allowed;
    box-shadow: inset 0 0 18px rgba(0,0,0,.6);
  }

  .icon {
    font-size: 1.95rem;
    line-height: 1;
  }

  .label {
    position: absolute;
    bottom: 5px;
    right: 7px;
    font-size: .62rem;
    color: var(--muted);
    font-weight: 900;
    letter-spacing: .03em;
  }

  .step-num {
    position: absolute;
    top: 5px;
    left: 6px;
    min-width: 19px;
    height: 19px;
    padding: 0 5px;
    border-radius: 999px;
    display: grid;
    place-items: center;
    color: white;
    font-size: .7rem;
    font-weight: 900;
  }

  .cell.planned {
    background: linear-gradient(145deg, rgba(255,209,102,.50), rgba(46,46,79,.95));
    border-color: rgba(255,209,102,.88);
  }

  .cell.planned .step-num {
    background: var(--plan);
    color: #20170a;
  }

  .cell.ran {
    background: linear-gradient(145deg, rgba(93,140,255,.55), rgba(46,46,79,.95));
    border-color: rgba(121,199,255,.8);
  }

  .cell.ran .step-num {
    background: var(--path);
  }

  .cell.current {
    outline: 3px solid var(--good);
    outline-offset: 2px;
  }

  .cell.cursor {
    border-color: var(--good);
    box-shadow: 0 0 0 3px rgba(117,240,168,.14), inset 0 -8px 15px rgba(0,0,0,.14);
  }

  .cell.keyboard-cursor {
    outline: 3px solid rgba(255,255,255,.75);
    outline-offset: 2px;
  }

  .cell.next-plan {
    border-color: var(--plan);
    box-shadow: 0 0 0 3px rgba(255,209,102,.15), inset 0 -8px 15px rgba(0,0,0,.14);
  }

  .cell.blocked {
    opacity: .58;
  }

  .cell.failed {
    border-color: var(--bad);
    box-shadow: 0 0 0 4px rgba(255,111,145,.25), inset 0 -8px 15px rgba(0,0,0,.14);
    animation: failPulse 1s infinite;
  }

  .cell.dead-end {
    border-color: var(--warn);
    box-shadow: 0 0 0 4px rgba(255,209,102,.22), inset 0 -8px 15px rgba(0,0,0,.14);
  }

  @keyframes failPulse {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-2px); }
  }

  .cell.exit-ready {
    animation: pulse 1.2s infinite;
  }

  @keyframes pulse {
    0%, 100% {
      box-shadow: 0 0 0 0 rgba(117,240,168,.32), inset 0 -8px 15px rgba(0,0,0,.14);
    }
    50% {
      box-shadow: 0 0 0 7px rgba(117,240,168,0), inset 0 -8px 15px rgba(0,0,0,.14);
    }
  }

  .side-panel {
    padding: 18px;
    position: sticky;
    top: 18px;
    max-height: calc(100vh - 36px);
    overflow: auto;
    -webkit-overflow-scrolling: touch;
  }

  .side-section {
    background: rgba(255,255,255,.045);
    border: 1px solid rgba(255,255,255,.075);
    border-radius: 17px;
    padding: 14px;
    margin-bottom: 12px;
  }

  .side-section h2 {
    font-size: 1rem;
    margin: 0 0 9px;
  }

  .rules {
    margin: 0;
    padding-left: 18px;
    color: var(--muted);
    line-height: 1.45;
  }

  .rules li {
    margin: 5px 0;
  }

  .legend {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    color: var(--muted);
  }

  .legend-item {
    background: rgba(0,0,0,.16);
    border-radius: 12px;
    padding: 8px;
    font-size: .88rem;
  }

  .message {
    min-height: 48px;
    color: var(--text);
    line-height: 1.4;
    font-weight: 750;
  }

  .message.good { color: var(--good); }
  .message.bad { color: var(--bad); }
  .message.warn { color: var(--warn); }

  .path-list {
    color: var(--muted);
    font-size: .9rem;
    line-height: 1.4;
    max-height: 190px;
    overflow: auto;
    -webkit-overflow-scrolling: touch;
  }

  .path-row {
    display: grid;
    grid-template-columns: 28px minmax(0, 1fr) auto;
    gap: 8px;
    padding: 6px 0;
    border-bottom: 1px solid rgba(255,255,255,.06);
  }

  .path-row:last-child {
    border-bottom: 0;
  }

  .path-row.ok .badge { color: var(--good); }
  .path-row.bad .badge { color: var(--bad); }
  .path-row.pending .badge { color: var(--warn); }

  .level-note,
  .mini-help {
    color: var(--muted);
    line-height: 1.45;
    margin: 0;
  }

  .score-card,
  .breakdown-card {
    display: grid;
    gap: 8px;
  }

  .score-line,
  .breakdown-line {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    padding: 8px 0;
    border-bottom: 1px solid rgba(255,255,255,.06);
    color: var(--muted);
  }

  .score-line:last-child,
  .breakdown-line:last-child {
    border-bottom: 0;
  }

  .score-line strong,
  .breakdown-line strong {
    color: var(--text);
    text-align: right;
  }

  .breakdown-box {
    border-radius: 14px;
    padding: 11px;
    background: rgba(255,111,145,.09);
    border: 1px solid rgba(255,111,145,.16);
    color: #ffdce4;
    line-height: 1.4;
    margin-bottom: 8px;
  }

  .breakdown-box.empty {
    background: rgba(117,240,168,.07);
    border-color: rgba(117,240,168,.12);
    color: var(--muted);
  }

  .hint-box {
    display: none;
    margin-top: 10px;
    border-radius: 14px;
    padding: 11px;
    background: rgba(255,209,102,.1);
    border: 1px solid rgba(255,209,102,.2);
    color: #ffe7a3;
    line-height: 1.4;
  }

  .tiny {
    font-size: .82rem;
    color: var(--muted);
    line-height: 1.35;
  }

  kbd {
    display: inline-block;
    border: 1px solid rgba(255,255,255,.2);
    border-bottom-width: 2px;
    border-radius: 6px;
    padding: 1px 6px;
    margin: 0 1px;
    background: rgba(0,0,0,.22);
    color: var(--text);
    font-size: .78em;
    font-weight: 800;
  }

  @media (max-width: 1020px) {
    body {
      padding: 12px;
    }

    .app {
      grid-template-columns: 1fr;
    }

    .side-panel {
      position: static;
      max-height: none;
      overflow: visible;
    }

    .stats {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .cell {
      width: clamp(48px, 9.5vw, 64px);
      height: clamp(48px, 9.5vw, 64px);
      border-radius: 13px;
    }

    .icon {
      font-size: clamp(1.25rem, 4.3vw, 1.65rem);
    }
  }

  @media (max-width: 620px) {
    body {
      padding: 10px;
    }

    header,
    .game-panel,
    .side-panel {
      border-radius: 17px;
      padding: 14px;
    }

    .topbar {
      display: grid;
      grid-template-columns: 1fr;
    }

    select {
      width: 100%;
      min-width: 0;
    }

    .controls {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px;
    }

    .controls button {
      min-height: 44px;
      width: 100%;
      padding: 10px 8px;
      font-size: .92rem;
    }

    .stats {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px;
    }

    .stat {
      padding: 9px 10px;
      border-radius: 13px;
    }

    .grid-wrap {
      padding: 6px;
      border-radius: 14px;
    }

    .grid {
      gap: 5px;
    }

    .cell {
      width: clamp(40px, 11.25vw, 52px);
      height: clamp(40px, 11.25vw, 52px);
      border-radius: 10px;
    }

    .icon {
      font-size: clamp(1.05rem, 5vw, 1.35rem);
    }

    .label {
      display: none;
    }

    .step-num {
      top: 3px;
      left: 3px;
      min-width: 17px;
      height: 17px;
      padding: 0 4px;
      font-size: .64rem;
    }

    .legend {
      grid-template-columns: 1fr 1fr;
    }

    .path-row {
      grid-template-columns: 22px minmax(0, 1fr);
    }

    .path-row span:last-child {
      grid-column: 2;
      font-size: .8rem;
      color: var(--muted);
    }

    .score-line,
    .breakdown-line {
      align-items: flex-start;
      flex-direction: column;
      gap: 3px;
    }

    .score-line strong,
    .breakdown-line strong {
      text-align: left;
    }
  }

  @media (max-width: 390px) {
    .cell {
      width: 38px;
      height: 38px;
    }

    .grid {
      gap: 4px;
    }

    .controls {
      grid-template-columns: 1fr;
    }
  }
</style>
</head>
<body>
  <main class="app">
    <header>
      <h1>Dungeon Route Puzzle</h1>
      <p class="subtitle">
        Sketch the full route first, then run it. Works with mouse, touch, or keyboard:
        <kbd>Arrow Keys</kbd> plan movement, <kbd>Enter</kbd> runs the route, and <kbd>Backspace</kbd> undoes the last step.
      </p>
    </header>

    <section class="game-panel">
      <div class="topbar">
        <select id="levelSelect" aria-label="Choose level"></select>
        <div class="controls">
          <button id="undoPlanBtn">Undo Step</button>
          <button id="clearPlanBtn">Clear Plan</button>
          <button id="runBtn" class="gold">Run Route</button>
          <button id="resetBtn" class="danger">Reset</button>
          <button id="nextBtn" class="primary">Next Level</button>
        </div>
      </div>

      <div class="stats">
        <div class="stat"><b>Mode</b><span id="modeText">Plan</span></div>
        <div class="stat"><b>Health</b><span id="hpText">3</span></div>
        <div class="stat"><b>Keys</b><span id="keyText">0</span></div>
        <div class="stat"><b>Planned</b><span id="plannedText">0</span></div>
        <div class="stat"><b>Par</b><span id="parText">0</span></div>
        <div class="stat"><b>Best</b><span id="bestText">—</span></div>
      </div>

      <div class="grid-wrap" id="gridWrap">
        <div id="grid" class="grid"></div>
      </div>
    </section>

    <aside class="side-panel">
      <div class="side-section">
        <h2>Current Puzzle</h2>
        <p id="levelNote" class="level-note"></p>
        <button id="hintBtn" class="hint-btn">Show Hint</button>
        <div id="hintBox" class="hint-box"></div>
      </div>

      <div class="side-section">
        <h2>Route Quality</h2>
        <div class="score-card">
          <div class="score-line">
            <span>Target par</span>
            <strong id="scorePar">0 steps</strong>
          </div>
          <div class="score-line">
            <span>Best solved route</span>
            <strong id="scoreBest">—</strong>
          </div>
          <div class="score-line">
            <span>Last result</span>
            <strong id="scoreLast">Not run</strong>
          </div>
        </div>
        <p class="tiny">
          Perfect means at or under par. Clean means within 3 steps of par. Too long means solved, but inefficient.
        </p>
      </div>

      <div class="side-section">
        <h2>Failed Run Breakdown</h2>
        <div id="breakdownBox" class="breakdown-box empty">
          Run a route. If it fails, this will show the exact breaking step and why.
        </div>
        <div class="breakdown-card">
          <div class="breakdown-line">
            <span>Breaking step</span>
            <strong id="breakStep">—</strong>
          </div>
          <div class="breakdown-line">
            <span>Failure type</span>
            <strong id="breakType">—</strong>
          </div>
          <div class="breakdown-line">
            <span>Fix focus</span>
            <strong id="breakFix">—</strong>
          </div>
        </div>
      </div>

      <div class="side-section">
        <h2>Controls</h2>
        <p class="mini-help">
          Tap or click adjacent rooms to sketch. Keyboard users can use <kbd>Arrow Keys</kbd> to add route steps,
          <kbd>Backspace</kbd> to undo, <kbd>Enter</kbd> to run, and <kbd>Esc</kbd> to reset the run.
        </p>
      </div>

      <div class="side-section">
        <h2>Status</h2>
        <div id="message" class="message">Plan your route from the start room.</div>
      </div>

      <div class="side-section">
        <h2>Rules</h2>
        <ol class="rules">
          <li>Routes move only up, down, left, or right.</li>
          <li>Keys add to your key count.</li>
          <li>Locked doors consume one key.</li>
          <li>Traps cost one health.</li>
          <li>Cracked floors collapse after you leave them.</li>
          <li>You win only if the route reaches the exit alive.</li>
        </ol>
      </div>

      <div class="side-section">
        <h2>Legend</h2>
        <div class="legend">
          <div class="legend-item">🧍 Start</div>
          <div class="legend-item">🔑 Key</div>
          <div class="legend-item">🔒 Door</div>
          <div class="legend-item">☠️ Trap</div>
          <div class="legend-item">🕳️ Crack</div>
          <div class="legend-item">🏁 Exit</div>
          <div class="legend-item">🧱 Wall</div>
          <div class="legend-item">⬚ Room</div>
        </div>
      </div>

      <div class="side-section">
        <h2>Your Planned Route</h2>
        <div id="pathList" class="path-list">Start</div>
      </div>
    </aside>
  </main>

<script>
(() => {
  const STORAGE_KEY = "dungeonRoutePuzzleBestSteps_v1";

  const levels = [
    {
      name: "Level 1: First Lock",
      hp: 3,
      par: 12,
      note: "Plan the whole path: collect the key, spend it on the locked door, then reach the exit.",
      hint: "The locked door is not the first objective. Your route needs to reach the key before it crosses the door.",
      map: [
        "#######",
        "#S..K.#",
        "#.###.#",
        "#...#L#",
        "###.#.#",
        "#.....E",
        "#######"
      ]
    },
    {
      name: "Level 2: Trap Toll",
      hp: 2,
      par: 13,
      note: "You can survive one trap, but not two. A valid plan needs the key and a safe route to the door.",
      hint: "Treat health like a key you can spend once. Avoid planning through both trap rooms.",
      map: [
        "########",
        "#S..T..#",
        "###.##.#",
        "#K..#L.#",
        "#.###..#",
        "#....T.E",
        "########"
      ]
    },
    {
      name: "Level 3: Collapsing Floor",
      hp: 3,
      par: 14,
      note: "Cracked floors collapse after your route leaves them. Do not plan to step on the same crack twice.",
      hint: "A cracked floor is safe once, but it cannot be part of a backtrack loop.",
      map: [
        "#########",
        "#S.C..K.#",
        "#.#.###.#",
        "#.#...#.#",
        "#.###.#L#",
        "#...C...E",
        "#########"
      ]
    },
    {
      name: "Level 4: Two Doors",
      hp: 3,
      par: 18,
      note: "Two keys, two doors. Route order matters because each door consumes a key.",
      hint: "Count doors before you commit. If you spend the first key too early, the second door will punish the route.",
      map: [
        "#########",
        "#S..K...#",
        "###.###L#",
        "#...#...#",
        "#.K.#.###",
        "#...L...E",
        "#########"
      ]
    },
    {
      name: "Level 5: The Clean Route",
      hp: 2,
      par: 20,
      note: "A compact final puzzle: one trap is survivable, but the wrong detour ruins the route.",
      hint: "You probably need one painful shortcut, but not every dangerous-looking room is worth entering.",
      map: [
        "##########",
        "#S...#...#",
        "#.##.#.K.#",
        "#..T.#.#L#",
        "##.#...#.#",
        "#K.###.#.#",
        "#....L...E",
        "##########"
      ]
    }
  ];

  const icons = {
    "#": "🧱",
    ".": "",
    "S": "🧍",
    "K": "🔑",
    "L": "🔒",
    "T": "☠️",
    "E": "🏁",
    "C": "🕳️"
  };

  const names = {
    "#": "Wall",
    ".": "Room",
    "S": "Start",
    "K": "Key",
    "L": "Door",
    "T": "Trap",
    "E": "Exit",
    "C": "Crack"
  };

  const gridEl = document.getElementById("grid");
  const gridWrap = document.getElementById("gridWrap");
  const levelSelect = document.getElementById("levelSelect");
  const undoPlanBtn = document.getElementById("undoPlanBtn");
  const clearPlanBtn = document.getElementById("clearPlanBtn");
  const runBtn = document.getElementById("runBtn");
  const resetBtn = document.getElementById("resetBtn");
  const nextBtn = document.getElementById("nextBtn");
  const hintBtn = document.getElementById("hintBtn");
  const hintBox = document.getElementById("hintBox");

  const hpText = document.getElementById("hpText");
  const keyText = document.getElementById("keyText");
  const plannedText = document.getElementById("plannedText");
  const parText = document.getElementById("parText");
  const bestText = document.getElementById("bestText");
  const modeText = document.getElementById("modeText");

  const scorePar = document.getElementById("scorePar");
  const scoreBest = document.getElementById("scoreBest");
  const scoreLast = document.getElementById("scoreLast");

  const breakdownBox = document.getElementById("breakdownBox");
  const breakStep = document.getElementById("breakStep");
  const breakType = document.getElementById("breakType");
  const breakFix = document.getElementById("breakFix");

  const messageEl = document.getElementById("message");
  const pathList = document.getElementById("pathList");
  const levelNote = document.getElementById("levelNote");

  let levelIndex = 0;
  let baseMap = [];
  let plan = [];
  let sim = null;
  let mode = "plan";
  let failedCell = null;
  let deadEndCell = null;
  let lastQuality = "Not run";
  let bestSteps = loadBestSteps();
  let failure = null;
  let hintShown = false;
  let keyboardCursor = null;

  levels.forEach((level, index) => {
    const option = document.createElement("option");
    option.value = index;
    option.textContent = `${level.name} · Par ${level.par}`;
    levelSelect.appendChild(option);
  });

  function loadBestSteps() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : {};
    } catch {
      return {};
    }
  }

  function saveBestSteps() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(bestSteps));
  }

  function cloneMap(map) {
    return map.map(row => row.split(""));
  }

  function findStart(map) {
    for (let y = 0; y < map.length; y++) {
      for (let x = 0; x < map[y].length; x++) {
        if (map[y][x] === "S") return { x, y };
      }
    }
    return { x: 0, y: 0 };
  }

  function keyOf(x, y) {
    return `${x},${y}`;
  }

  function inBounds(map, x, y) {
    return y >= 0 && y < map.length && x >= 0 && x < map[y].length;
  }

  function getTile(map, x, y) {
    if (!inBounds(map, x, y)) return "#";
    return map[y][x];
  }

  function isAdjacent(a, b) {
    return Math.abs(a.x - b.x) + Math.abs(a.y - b.y) === 1;
  }

  function startLevel(index) {
    levelIndex = index;
    const level = levels[levelIndex];
    baseMap = cloneMap(level.map);
    const start = findStart(baseMap);

    plan = [{ x: start.x, y: start.y, tile: "S" }];
    sim = makeFreshSim();
    mode = "plan";
    failedCell = null;
    deadEndCell = null;
    lastQuality = "Not run";
    failure = null;
    hintShown = false;
    keyboardCursor = { ...start };

    levelSelect.value = String(levelIndex);
    levelNote.textContent = level.note;
    hintBox.style.display = "none";
    hintBox.textContent = "";
    hintBtn.textContent = "Show Hint";

    setMessage(`Plan the full route first. Par is ${level.par} steps.`);
    render();
    centerKeyboardCursor();
  }

  function makeFreshSim() {
    const level = levels[levelIndex];
    const map = cloneMap(level.map);
    const start = findStart(map);

    return {
      map,
      hp: level.hp,
      keys: 0,
      pos: start,
      ranPath: [{ x: start.x, y: start.y, tile: "S" }],
      collapsed: new Set(),
      won: false,
      lost: false,
      currentStep: 0,
      result: "Not run"
    };
  }

  function setMessage(text, type = "") {
    messageEl.textContent = text;
    messageEl.className = `message ${type}`;
  }

  function plannedCursor() {
    return plan[plan.length - 1];
  }

  function getQuality(steps) {
    const par = levels[levelIndex].par;

    if (steps <= par) {
      return {
        label: "Perfect",
        className: "quality-perfect",
        message: `Perfect route: ${steps} steps against par ${par}.`
      };
    }

    if (steps <= par + 3) {
      return {
        label: "Clean",
        className: "quality-clean",
        message: `Clean route: ${steps} steps. Par is ${par}, so there is still room to tighten it.`
      };
    }

    return {
      label: "Too long",
      className: "quality-long",
      message: `Solved, but too long: ${steps} steps against par ${par}. Try cutting detours.`
    };
  }

  function updateBestIfNeeded(steps) {
    const key = String(levelIndex);
    const currentBest = bestSteps[key];

    if (currentBest === undefined || steps < currentBest) {
      bestSteps[key] = steps;
      saveBestSteps();
      return true;
    }

    return false;
  }

  function getBestForCurrentLevel() {
    const value = bestSteps[String(levelIndex)];
    return typeof value === "number" ? value : null;
  }

  function formatBest() {
    const best = getBestForCurrentLevel();
    if (best === null) return "—";
    const quality = getQuality(best);
    return `${best} · ${quality.label}`;
  }

  function classifyFailure(type, step, x, y, detail) {
    const labels = {
      missing_key: "Missing key",
      trap_death: "Trap death",
      collapsed_floor: "Collapsed floor",
      wall: "Wall",
      dead_end: "Dead end",
      not_adjacent: "Broken route",
      after_exit: "After exit",
      incomplete: "Incomplete route"
    };

    const fixes = {
      missing_key: "Collect a key before this door.",
      trap_death: "Preserve health before this trap.",
      collapsed_floor: "Avoid backtracking over a cracked room.",
      wall: "Route around the wall.",
      dead_end: "Do not end here unless this room is the exit.",
      not_adjacent: "Remove the jump and connect the path one room at a time.",
      after_exit: "Stop the route at the exit.",
      incomplete: "Extend the route until the final step lands on the exit."
    };

    return {
      type,
      step,
      x,
      y,
      label: labels[type] || "Route failure",
      fix: fixes[type] || "Adjust the route before this step.",
      detail
    };
  }

  function planStep(x, y) {
    if (mode === "running") return;

    failedCell = null;
    deadEndCell = null;
    failure = null;

    const last = plannedCursor();
    const previous = plan[plan.length - 2];

    if (previous && previous.x === x && previous.y === y) {
      plan.pop();
      sim = makeFreshSim();
      mode = "plan";
      lastQuality = "Not run";
      keyboardCursor = { ...plannedCursor() };
      setMessage("Backed up one planned step.");
      render();
      centerKeyboardCursor();
      return;
    }

    if (!isAdjacent(last, { x, y })) {
      setMessage("Plan routes one adjacent room at a time.", "bad");
      keyboardCursor = { x, y };
      render();
      centerKeyboardCursor();
      return;
    }

    const tile = getTile(baseMap, x, y);

    if (tile === "#") {
      setMessage("Walls cannot be added to the route.", "bad");
      keyboardCursor = { x, y };
      render();
      centerKeyboardCursor();
      return;
    }

    plan.push({ x, y, tile });
    keyboardCursor = { x, y };
    sim = makeFreshSim();
    mode = "plan";
    lastQuality = "Not run";

    const preview = validatePlan(false);

    if (preview.ok) {
      if (tile === "E") {
        const plannedSteps = plan.length - 1;
        const quality = getQuality(plannedSteps);
        setMessage(`Route reaches the exit in ${plannedSteps} steps. Run it to confirm: ${quality.label}.`, "good");
      } else {
        setMessage("Step added. Keep planning or run the route.");
      }
    } else {
      setMessage(`Plan warning at step ${preview.failStep}: ${preview.reason}`, "warn");
    }

    render();
    centerKeyboardCursor();
  }

  function validatePlan(stopAtFailure = true) {
    const test = makeFreshSim();

    for (let i = 1; i < plan.length; i++) {
      const target = plan[i];
      const result = applyMove(test, target.x, target.y, i);

      if (!result.ok) {
        return {
          ok: false,
          failStep: i,
          reason: result.reason,
          x: target.x,
          y: target.y,
          type: result.type
        };
      }

      if (result.won && i < plan.length - 1) {
        return {
          ok: false,
          failStep: i + 1,
          reason: "the route keeps going after the exit",
          x: plan[i + 1].x,
          y: plan[i + 1].y,
          type: "after_exit"
        };
      }

      if (stopAtFailure && result.won) break;
    }

    const final = plan[plan.length - 1];
    const originalFinalTile = getTile(baseMap, final.x, final.y);

    if (originalFinalTile !== "E") {
      return {
        ok: false,
        failStep: plan.length - 1,
        reason: "the planned route does not end at the exit",
        x: final.x,
        y: final.y,
        type: "incomplete"
      };
    }

    return { ok: true, reason: "valid route" };
  }

  function applyMove(targetState, x, y, stepIndex) {
    const tile = getTile(targetState.map, x, y);
    const old = { ...targetState.pos };
    const oldTile = getTile(targetState.map, old.x, old.y);

    if (!isAdjacent(targetState.pos, { x, y })) {
      return { ok: false, type: "not_adjacent", reason: "that move is not adjacent" };
    }

    if (tile === "#") {
      return { ok: false, type: "wall", reason: "a wall blocks the route" };
    }

    if (targetState.collapsed.has(keyOf(x, y))) {
      return { ok: false, type: "collapsed_floor", reason: "that cracked floor has already collapsed" };
    }

    if (tile === "L" && targetState.keys < 1) {
      return { ok: false, type: "missing_key", reason: "the door needs one key" };
    }

    if (tile === "T" && targetState.hp <= 1) {
      return { ok: false, type: "trap_death", reason: "the trap would reduce health to zero" };
    }

    if (oldTile === "C") {
      targetState.collapsed.add(keyOf(old.x, old.y));
    }

    if (tile === "K") {
      targetState.keys += 1;
      targetState.map[y][x] = ".";
    }

    if (tile === "L") {
      targetState.keys -= 1;
      targetState.map[y][x] = ".";
    }

    if (tile === "T") {
      targetState.hp -= 1;
      targetState.map[y][x] = ".";
    }

    targetState.pos = { x, y };
    targetState.currentStep = stepIndex;
    targetState.ranPath.push({ x, y, tile });

    if (tile === "E") {
      targetState.won = true;
      targetState.result = "Escaped";
      return { ok: true, won: true, reason: "escaped" };
    }

    return { ok: true, won: false, reason: "moved" };
  }

  function hasAnyLegalMoveFrom(testState) {
    const dirs = [
      { x: 1, y: 0 },
      { x: -1, y: 0 },
      { x: 0, y: 1 },
      { x: 0, y: -1 }
    ];

    return dirs.some(d => {
      const nx = testState.pos.x + d.x;
      const ny = testState.pos.y + d.y;
      const tile = getTile(testState.map, nx, ny);

      if (tile === "#") return false;
      if (testState.collapsed.has(keyOf(nx, ny))) return false;
      if (tile === "L" && testState.keys < 1) return false;
      if (tile === "T" && testState.hp <= 1) return false;

      return true;
    });
  }

  function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  async function runRoute() {
    if (mode === "running") return;

    failedCell = null;
    deadEndCell = null;
    failure = null;

    if (plan.length < 2) {
      failure = classifyFailure(
        "incomplete",
        0,
        plannedCursor().x,
        plannedCursor().y,
        "You have not sketched any route yet."
      );
      setMessage("Sketch a route before running it.", "bad");
      render();
      return;
    }

    mode = "running";
    sim = makeFreshSim();
    lastQuality = "Running";
    setMessage("Running route...");
    render();

    for (let i = 1; i < plan.length; i++) {
      await sleep(330);

      const target = plan[i];
      const result = applyMove(sim, target.x, target.y, i);

      if (!result.ok) {
        mode = "failed";
        sim.lost = true;
        sim.result = "Failed";
        lastQuality = "Failed";
        failedCell = { x: target.x, y: target.y };
        keyboardCursor = { ...failedCell };
        failure = classifyFailure(result.type, i, target.x, target.y, result.reason);
        setMessage(`Route failed at step ${i}: ${result.reason}.`, "bad");
        render();
        centerKeyboardCursor();
        return;
      }

      keyboardCursor = { x: target.x, y: target.y };
      render();
      centerKeyboardCursor();

      if (result.won) {
        if (i === plan.length - 1) {
          const steps = i;
          const quality = getQuality(steps);
          const isNewBest = updateBestIfNeeded(steps);

          mode = "won";
          lastQuality = `${steps} · ${quality.label}`;
          sim.result = quality.label;

          const extra = isNewBest ? " New best saved." : "";
          const messageType = quality.label === "Perfect" ? "good" : quality.label === "Clean" ? "warn" : "bad";
          setMessage(`${quality.message}${extra}`, messageType);
          render();
          centerKeyboardCursor();
          return;
        }

        await sleep(250);
        mode = "failed";
        sim.lost = true;
        sim.result = "Failed";
        lastQuality = "Failed";
        failedCell = { x: plan[i + 1].x, y: plan[i + 1].y };
        keyboardCursor = { ...failedCell };
        failure = classifyFailure(
          "after_exit",
          i + 1,
          plan[i + 1].x,
          plan[i + 1].y,
          `You escaped at step ${i}, then planned extra moves after the exit.`
        );
        setMessage(`Route reached the exit at step ${i}, but your plan keeps going after the exit.`, "bad");
        render();
        centerKeyboardCursor();
        return;
      }
    }

    const final = plan[plan.length - 1];

    if (!hasAnyLegalMoveFrom(sim)) {
      mode = "failed";
      sim.result = "Dead end";
      lastQuality = "Dead end";
      deadEndCell = { x: final.x, y: final.y };
      keyboardCursor = { ...deadEndCell };
      failure = classifyFailure(
        "dead_end",
        plan.length - 1,
        final.x,
        final.y,
        "Your route ended in a room with no legal continuation to the exit."
      );
      setMessage("Route hit a dead end before reaching the exit.", "bad");
      render();
      centerKeyboardCursor();
      return;
    }

    mode = "failed";
    sim.result = "Incomplete";
    lastQuality = "Incomplete";
    failedCell = { x: final.x, y: final.y };
    keyboardCursor = { ...failedCell };
    failure = classifyFailure(
      "incomplete",
      plan.length - 1,
      final.x,
      final.y,
      "The route is legal so far, but it stops before the exit."
    );
    setMessage("Route ended without reaching the exit.", "bad");
    render();
    centerKeyboardCursor();
  }

  function undoPlan() {
    if (mode === "running") return;
    if (plan.length <= 1) return;

    plan.pop();
    sim = makeFreshSim();
    mode = "plan";
    failedCell = null;
    deadEndCell = null;
    failure = null;
    lastQuality = "Not run";
    keyboardCursor = { ...plannedCursor() };
    setMessage("Removed the last planned step.");
    render();
    centerKeyboardCursor();
  }

  function clearPlan() {
    if (mode === "running") return;

    const start = findStart(baseMap);
    plan = [{ x: start.x, y: start.y, tile: "S" }];
    sim = makeFreshSim();
    mode = "plan";
    failedCell = null;
    deadEndCell = null;
    failure = null;
    lastQuality = "Not run";
    keyboardCursor = { ...start };
    setMessage("Plan cleared. Sketch a new route.");
    render();
    centerKeyboardCursor();
  }

  function resetRunOnly() {
    if (mode === "running") return;

    sim = makeFreshSim();
    failedCell = null;
    deadEndCell = null;
    failure = null;
    mode = "plan";
    lastQuality = "Not run";
    keyboardCursor = { ...plannedCursor() };
    setMessage("Run reset. Your planned route is still on the board.");
    render();
    centerKeyboardCursor();
  }

  function getNextPlanCandidates() {
    if (mode === "running") return new Set();

    const last = plannedCursor();
    const dirs = [
      { x: 1, y: 0 },
      { x: -1, y: 0 },
      { x: 0, y: 1 },
      { x: 0, y: -1 }
    ];

    return new Set(
      dirs
        .map(d => ({ x: last.x + d.x, y: last.y + d.y }))
        .filter(p => getTile(baseMap, p.x, p.y) !== "#")
        .map(p => keyOf(p.x, p.y))
    );
  }

  function render() {
    const level = levels[levelIndex];
    const rows = baseMap.length;
    const cols = Math.max(...baseMap.map(r => r.length));
    const nextCandidates = getNextPlanCandidates();

    const planMap = new Map();
    plan.forEach((p, i) => {
      planMap.set(keyOf(p.x, p.y), i);
    });

    const ranMap = new Map();
    if (sim) {
      sim.ranPath.forEach((p, i) => {
        ranMap.set(keyOf(p.x, p.y), i);
      });
    }

    gridEl.innerHTML = "";
    gridEl.style.gridTemplateColumns = `repeat(${cols}, 1fr)`;

    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        const liveMap = mode === "running" || mode === "won" || mode === "failed" ? sim.map : baseMap;
        const tile = getTile(liveMap, x, y);
        const baseTile = getTile(baseMap, x, y);
        const cell = document.createElement("button");

        cell.className = "cell";
        cell.type = "button";
        cell.dataset.x = String(x);
        cell.dataset.y = String(y);
        cell.setAttribute("aria-label", `${names[baseTile] || "Room"} at row ${y + 1}, column ${x + 1}`);

        if (baseTile === "#") cell.classList.add("wall");
        if (sim && sim.collapsed.has(keyOf(x, y))) cell.classList.add("wall");

        if (planMap.has(keyOf(x, y))) cell.classList.add("planned");
        if (ranMap.has(keyOf(x, y))) cell.classList.add("ran");

        if (mode === "plan" && plannedCursor().x === x && plannedCursor().y === y) {
          cell.classList.add("cursor");
        }

        if (keyboardCursor && keyboardCursor.x === x && keyboardCursor.y === y) {
          cell.classList.add("keyboard-cursor");
        }

        if (sim && sim.pos.x === x && sim.pos.y === y && mode !== "plan") {
          cell.classList.add("current");
        }

        if (nextCandidates.has(keyOf(x, y)) && mode === "plan") {
          cell.classList.add("next-plan");
        }

        if (failedCell && failedCell.x === x && failedCell.y === y) {
          cell.classList.add("failed");
        }

        if (deadEndCell && deadEndCell.x === x && deadEndCell.y === y) {
          cell.classList.add("dead-end");
        }

        if (baseTile === "E" && nextCandidates.has(keyOf(x, y))) {
          cell.classList.add("exit-ready");
        }

        const icon = document.createElement("div");
        icon.className = "icon";

        if (sim && sim.collapsed.has(keyOf(x, y))) {
          icon.textContent = "⬛";
        } else {
          icon.textContent = icons[tile] || icons[baseTile] || "";
        }

        cell.appendChild(icon);

        if (baseTile !== "." && baseTile !== "#") {
          const label = document.createElement("div");
          label.className = "label";
          label.textContent = names[baseTile];
          cell.appendChild(label);
        }

        const stepIndex = ranMap.has(keyOf(x, y)) ? ranMap.get(keyOf(x, y)) : planMap.get(keyOf(x, y));

        if (stepIndex !== undefined) {
          const step = document.createElement("div");
          step.className = "step-num";
          step.textContent = stepIndex;
          cell.appendChild(step);
        }

        if (baseTile === "#" || mode === "running") {
          cell.disabled = true;
        }

        if (!nextCandidates.has(keyOf(x, y)) && !planMap.has(keyOf(x, y)) && baseTile !== "#") {
          cell.classList.add("blocked");
        }

        cell.addEventListener("click", () => {
          keyboardCursor = { x, y };
          planStep(x, y);
        });

        gridEl.appendChild(cell);
      }
    }

    const best = getBestForCurrentLevel();

    hpText.textContent = sim ? ("❤️".repeat(sim.hp) || "0") : "0";
    keyText.textContent = sim && sim.keys > 0 ? `🔑 ${sim.keys}` : "0";
    plannedText.textContent = String(Math.max(0, plan.length - 1));
    parText.textContent = String(level.par);
    bestText.textContent = best === null ? "—" : String(best);
    modeText.textContent =
      mode === "running" ? "Running" :
      mode === "won" ? "Solved" :
      mode === "failed" ? "Failed" :
      "Plan";

    scorePar.textContent = `${level.par} steps`;
    scoreBest.textContent = formatBest();
    scoreLast.textContent = lastQuality;
    scoreLast.className = "";
    if (lastQuality.includes("Perfect")) scoreLast.classList.add("quality-perfect");
    if (lastQuality.includes("Clean")) scoreLast.classList.add("quality-clean");
    if (lastQuality.includes("Too long")) scoreLast.classList.add("quality-long");

    renderFailureBreakdown();

    undoPlanBtn.disabled = mode === "running" || plan.length <= 1;
    clearPlanBtn.disabled = mode === "running" || plan.length <= 1;
    runBtn.disabled = mode === "running" || plan.length <= 1;
    resetBtn.disabled = mode === "running";
    nextBtn.disabled = mode === "running" || levelIndex >= levels.length - 1;

    renderPathList();
  }

  function renderFailureBreakdown() {
    if (!failure) {
      breakdownBox.className = "breakdown-box empty";
      breakdownBox.textContent = "Run a route. If it fails, this will show the exact breaking step and why.";
      breakStep.textContent = "—";
      breakType.textContent = "—";
      breakFix.textContent = "—";
      return;
    }

    breakdownBox.className = "breakdown-box";
    breakdownBox.textContent = failure.detail;
    breakStep.textContent = `${failure.step} at (${failure.x + 1},${failure.y + 1})`;
    breakType.textContent = failure.label;
    breakFix.textContent = failure.fix;
  }

  function renderPathList() {
    if (plan.length === 1) {
      pathList.innerHTML = `<div class="path-row ok"><span class="badge">●</span><span>0. Start</span><span></span></div>`;
      return;
    }

    const preview = previewRows();

    pathList.innerHTML = preview.map(row => {
      const cls = row.status === "ok" ? "ok" : row.status === "bad" ? "bad" : "pending";
      const badge = row.status === "ok" ? "✓" : row.status === "bad" ? "!" : "•";

      return `
        <div class="path-row ${cls}">
          <span class="badge">${badge}</span>
          <span>${row.text}</span>
          <span>${row.meta}</span>
        </div>
      `;
    }).join("");
  }

  function previewRows() {
    const rows = [];
    const test = makeFreshSim();

    rows.push({
      status: "ok",
      text: "0. Start",
      meta: `❤️${test.hp} 🔑${test.keys}`
    });

    let failed = false;

    for (let i = 1; i < plan.length; i++) {
      const p = plan[i];

      if (failed) {
        rows.push({
          status: "pending",
          text: `${i}. ${names[p.tile] || "Room"} (${p.x + 1},${p.y + 1})`,
          meta: "not checked"
        });
        continue;
      }

      const result = applyMove(test, p.x, p.y, i);

      if (!result.ok) {
        failed = true;
        rows.push({
          status: "bad",
          text: `${i}. ${names[p.tile] || "Room"} (${p.x + 1},${p.y + 1})`,
          meta: result.reason
        });
      } else {
        rows.push({
          status: "ok",
          text: `${i}. ${names[p.tile] || "Room"} (${p.x + 1},${p.y + 1})`,
          meta: `❤️${test.hp} 🔑${test.keys}`
        });
      }
    }

    return rows;
  }

  function moveKeyboardCursor(dx, dy) {
    if (mode === "running") return;

    const cursor = keyboardCursor || plannedCursor();
    const nx = cursor.x + dx;
    const ny = cursor.y + dy;

    if (!inBounds(baseMap, nx, ny)) return;

    keyboardCursor = { x: nx, y: ny };

    if (isAdjacent(plannedCursor(), keyboardCursor) && getTile(baseMap, nx, ny) !== "#") {
      planStep(nx, ny);
    } else {
      setMessage("Keyboard cursor moved. Use an adjacent open room to extend the route.", "warn");
      render();
      centerKeyboardCursor();
    }
  }

  function centerKeyboardCursor() {
    if (!keyboardCursor) return;

    const selector = `.cell[data-x="${keyboardCursor.x}"][data-y="${keyboardCursor.y}"]`;
    const cell = gridEl.querySelector(selector);

    if (!cell) return;

    const wrapRect = gridWrap.getBoundingClientRect();
    const cellRect = cell.getBoundingClientRect();

    const outLeft = cellRect.left < wrapRect.left;
    const outRight = cellRect.right > wrapRect.right;
    const outTop = cellRect.top < wrapRect.top;
    const outBottom = cellRect.bottom > wrapRect.bottom;

    if (outLeft || outRight || outTop || outBottom) {
      cell.scrollIntoView({
        block: "nearest",
        inline: "nearest"
      });
    }
  }

  function shouldIgnoreKeyboard(event) {
    const tag = document.activeElement && document.activeElement.tagName;
    return tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT";
  }

  document.addEventListener("keydown", event => {
    if (shouldIgnoreKeyboard(event)) return;

    if (event.key === "ArrowUp") {
      event.preventDefault();
      moveKeyboardCursor(0, -1);
    } else if (event.key === "ArrowDown") {
      event.preventDefault();
      moveKeyboardCursor(0, 1);
    } else if (event.key === "ArrowLeft") {
      event.preventDefault();
      moveKeyboardCursor(-1, 0);
    } else if (event.key === "ArrowRight") {
      event.preventDefault();
      moveKeyboardCursor(1, 0);
    } else if (event.key === "Enter") {
      event.preventDefault();
      runRoute();
    } else if (event.key === "Backspace") {
      event.preventDefault();
      undoPlan();
    } else if (event.key === "Escape") {
      event.preventDefault();
      resetRunOnly();
    }
  });

  runBtn.addEventListener("click", runRoute);
  undoPlanBtn.addEventListener("click", undoPlan);
  clearPlanBtn.addEventListener("click", clearPlan);
  resetBtn.addEventListener("click", resetRunOnly);

  nextBtn.addEventListener("click", () => {
    if (levelIndex < levels.length - 1) startLevel(levelIndex + 1);
  });

  levelSelect.addEventListener("change", () => {
    startLevel(Number(levelSelect.value));
  });

  hintBtn.addEventListener("click", () => {
    hintShown = !hintShown;
    hintBox.style.display = hintShown ? "block" : "none";
    hintBox.textContent = levels[levelIndex].hint;
    hintBtn.textContent = hintShown ? "Hide Hint" : "Show Hint";
  });

  startLevel(0);
})();
</script>
